mapper.select:

where del_flag = '0'
and group_id = #{groupId}
and cx_machine_code = #{cxMachineCode}

    order by create_time desc


    order by ${orderStr}

select * from (
    select gml.id, gml.group_id, gml.cx_machine_code,cmi.machine_name as cxMachineName, gml.remark, gml.del_flag, gml.create_by, gml.create_time, gml.update_by, gml.update_time
    from t_cx_group_machine_list gml,t_cx_machine_info cmi
    where gml.del_flag = '0' and cmi.del_flag = '0' and gml.cx_machine_code=cmi.machine_code
    and gml.group_id = #{groupId}
    and gml.cx_machine_code = #{cxMachineCode}

        order by create_time desc

) t

    order by ${orderStr}

select gml.id, gml.group_id, gml.cx_machine_code,cmi.machine_name as cxMachineName, gml.remark, gml.del_flag, gml.create_by, gml.create_time, gml.update_by, gml.update_time
from t_cx_group_machine_list gml,t_cx_machine_info cmi
where gml.del_flag = '0' and cmi.del_flag = '0' and gml.cx_machine_code=cmi.machine_code
and gml.group_id != #{groupId}
and gml.cx_machine_code = #{cxMachineCode}

mapper.update:
update t_cx_group_machine_list
group_id = #{groupId}, cx_machine_code = #{cxMachineCode}, remark = #{remark}, del_flag = #{delFlag}, create_by = #{createBy}, create_time = #{createTime}, update_by = #{updateBy}, update_time = #{updateTime},
where id = #{id}
